function regoOn(el){ el.classList.remove("on"); void el.offsetWidth; el.classList.add("on"); }
function autoScroll(sc){ return async () => { sc.scrollTo({top:0}); await sleep(200); sc.scrollTo({top:sc.scrollHeight,behavior:"smooth"}); await sleep(1800); sc.scrollTo({top:0,behavior:"smooth"}); }; }
